import{_ as g,C as c,o as a,c as p,j as u,a as t,G as n,a3 as o,b as s,w as i,a9 as l}from"./chunks/framework.exbasbhr.js";const y=JSON.parse('{"title":"Configuration File Management","description":"Configuration File Management","frontmatter":{"date":"2026-05-05T00:00:00.000Z","author":["Makitoid","Qoder"],"title":"Configuration File Management","description":"Configuration File Management"},"headers":[],"relativePath":"en/dev/system-architecture/config-management/config-files.md","filePath":"en/dev/system-architecture/config-management/config-files.md"}'),f={name:"en/dev/system-architecture/config-management/config-files.md"};function m(h,e,A,C,P,k){const d=c("ArticleMetadata"),r=c("Mermaid");return a(),p("div",null,[e[4]||(e[4]=u("h1",{id:"configuration-file-management",tabindex:"-1"},[t("Configuration File Management "),u("a",{class:"header-anchor",href:"#configuration-file-management","aria-label":'Permalink to "Configuration File Management"'},"​")],-1)),n(d),e[5]||(e[5]=o('<h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>This document focuses on the configuration file management system of InkCanvasForClass, concentrating on the following topics:</p><ul><li>Configuration file structural design and storage locations</li><li>File formats and naming conventions</li><li>Loading workflows (existence checks, JSON parsing, exception handling)</li><li>Backup policies (trigger conditions, backup formats, recovery workflows)</li><li>Version control and migration (including backward compatibility and upgrade policies)</li><li>Manual editing guide (valid configuration entries, data type validation, recovery methods)</li><li>Security and integrity protection</li></ul><h2 id="project-structure" tabindex="-1">Project Structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project Structure&quot;">​</a></h2><p>InkCanvasForClass&#39;s configuration system centers around &quot;Main Configuration File + Multiple Profile Schemes + Automatic Backups&quot;:</p><ul><li>Main Configuration File: Configs/Settings.json (currently active configuration)</li><li>Profile Schemes: Configs/Profiles/*.json (multiple sets of schemes, hot-swappable)</li><li>Automatic Backups: Backups/ (backup files named by timestamps)</li><li>Hotkey Configuration: Configs/HotkeyConfig.json (standalone hotkey configuration file)</li></ul>',6)),(a(),s(l,null,{default:i(()=>[n(r,{id:"mermaid-74",class:"mermaid",graph:"graph%20TB%0Asubgraph%20%22Application%20Root%20Directory%22%0ACFG%5B%22Configs%2F%22%5D%0ABK%5B%22Backups%2F%22%5D%0APR%5B%22Configs%2FProfiles%2F%22%5D%0AST%5B%22Configs%2FSettings.json%22%5D%0AHK%5B%22Configs%2FHotkeyConfig.json%22%5D%0Aend%0ACFG%20--%3E%20ST%0ACFG%20--%3E%20PR%0ACFG%20--%3E%20HK%0ABK%20--%3E%20ST%0A"})]),fallback:i(()=>e[0]||(e[0]=[t(" Loading... ")])),_:1})),e[6]||(e[6]=o('<h2 id="core-components" tabindex="-1">Core Components <a class="header-anchor" href="#core-components" aria-label="Permalink to &quot;Core Components&quot;">​</a></h2><ul><li>Profile Scheme Manager: Responsible for scheme directory creation, scheme listing, saving as a scheme, applying a scheme, and deleting a scheme.</li><li>Automatic Backup Manager: Responsible for evaluating auto-backup triggers, executing backups, recovering from backups, and cleaning up expired backups.</li><li>Settings Model: Defines the structure of Settings and each submodule, used for serialization/deserialization.</li><li>Process Protection Manager: Provides a protected context when writing configuration files to avoid concurrency conflicts and external interference.</li><li>Application Entry Point: Responsible for reading the main configuration file and parsing critical settings during the startup phase.</li></ul><h2 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h2><p>Key interactions for configuration file management are as follows:</p><ul><li>Both the Profile Scheme Manager and the Automatic Backup Manager depend on the fixed path &quot;Application Root Path + Configs/Settings.json&quot;.</li><li>The Process Protection Manager provides lock and handle protection before and after write operations to reduce concurrency risks.</li><li>The Application Entry Point performs a lightweight read of Settings.json at startup to determine certain behaviors (like the splash screen).</li></ul>',5)),(a(),s(l,null,{default:i(()=>[n(r,{id:"mermaid-128",class:"mermaid",graph:"sequenceDiagram%0Aparticipant%20App%20as%20%22Application%20Entry%20(App)%22%0Aparticipant%20CfgMgr%20as%20%22Profile%20Manager%22%0Aparticipant%20BkMgr%20as%20%22Auto-Backup%20Manager%22%0Aparticipant%20ProcProt%20as%20%22Process%20Protection%20Manager%22%0Aparticipant%20FS%20as%20%22File%20System%22%0AApp-%3E%3EFS%20%3A%20Read%20%22Configs%2FSettings.json%22%0AFS--%3E%3EApp%20%3A%20Return%20JSON%20or%20not%20exist%0AApp-%3E%3EApp%20%3A%20Parse%20key%20settings%20such%20as%20splash%20screen%0ACfgMgr-%3E%3EProcProt%20%3A%20WithWriteAccess(ProfilesDir)%0AProcProt-%3E%3EFS%20%3A%20Create%20directory%0AProcProt--%3E%3ECfgMgr%20%3A%20Success%0ACfgMgr-%3E%3EProcProt%20%3A%20WithWriteAccess(ProfilePath)%0AProcProt-%3E%3EFS%20%3A%20Write%20profile%20file%0AProcProt--%3E%3ECfgMgr%20%3A%20Success%0ABkMgr-%3E%3EProcProt%20%3A%20WithWriteAccess(BackupDir)%0AProcProt-%3E%3EFS%20%3A%20Create%20backup%20directory%0AProcProt--%3E%3EBkMgr%20%3A%20Success%0ABkMgr-%3E%3EFS%20%3A%20Check%20if%20Settings.json%20exists%0ABkMgr-%3E%3EProcProt%20%3A%20WithWriteAccess(BackupPath)%0AProcProt-%3E%3EFS%20%3A%20Copy%20backup%0AProcProt--%3E%3EBkMgr%20%3A%20Success%0A"})]),fallback:i(()=>e[1]||(e[1]=[t(" Loading... ")])),_:1})),e[7]||(e[7]=o('<h2 id="detailed-component-analysis" tabindex="-1">Detailed Component Analysis <a class="header-anchor" href="#detailed-component-analysis" aria-label="Permalink to &quot;Detailed Component Analysis&quot;">​</a></h2><h3 id="profile-scheme-manager-configprofilemanager" tabindex="-1">Profile Scheme Manager (ConfigProfileManager) <a class="header-anchor" href="#profile-scheme-manager-configprofilemanager" aria-label="Permalink to &quot;Profile Scheme Manager (ConfigProfileManager)&quot;">​</a></h3><p>Responsibilities and Behaviors:</p><ul><li>Ensure the profile scheme directory exists (creates it automatically).</li><li>List saved scheme names (sorted alphabetically).</li><li>Serialize settings in memory to JSON and save as a new scheme.</li><li>Apply a specified scheme to the active configuration (overwriting Settings.json).</li><li>Delete a specified scheme.</li></ul><p>Key Implementation Points:</p><ul><li>Scheme Directory: ApplicationRootPath/Configs/Profiles</li><li>Scheme File Naming: Scheme name processed to be a &quot;safe filename&quot; and appended with <code>.json</code>.</li><li>Validates JSON legitimacy (deserialization test) when applying a scheme.</li><li>Wrap write operations with the Process Protection Manager to ensure concurrent safety.</li></ul>',6)),(a(),s(l,null,{default:i(()=>[n(r,{id:"mermaid-190",class:"mermaid",graph:"flowchart%20TD%0AStart(%5B%22Save%20as%20Profile%22%5D)%20--%3E%20CheckJson%5B%22Check%20if%20JSON%20is%20empty%22%5D%0ACheckJson%20--%3E%20%7CEmpty%7C%20Warn%5B%22Log%20warning%20and%20return%20failure%22%5D%0ACheckJson%20--%3E%20%7CNot%20empty%7C%20EnsureDir%5B%22EnsureProfilesDirectory()%22%5D%0AEnsureDir%20--%3E%20WriteFile%5B%22WithWriteAccess(ProfileFile)%20Write%22%5D%0AWriteFile%20--%3E%20Done(%5B%22Finished%22%5D)%0AApplyStart(%5B%22Apply%20Profile%22%5D)%20--%3E%20GetPath%5B%22GetProfilePath(ProfileName)%22%5D%0AGetPath%20--%3E%20Exists%7B%22File%20Exists%3F%22%7D%0AExists%20--%3E%20%7CNo%7C%20Warn2%5B%22Log%20warning%20and%20return%20failure%22%5D%0AExists%20--%3E%20%7CYes%7C%20ReadFile%5B%22Read%20file%20content%22%5D%0AReadFile%20--%3E%20Empty%7B%22Content%20Empty%3F%22%7D%0AEmpty%20--%3E%20%7CYes%7C%20Warn3%5B%22Log%20warning%20and%20return%20failure%22%5D%0AEmpty%20--%3E%20%7CNo%7C%20Validate%5B%22Deserialize%20to%20Settings%20to%20test%20validity%22%5D%0AValidate%20--%3E%20%7CFailure%7C%20Warn4%5B%22Log%20error%20and%20return%20failure%22%5D%0AValidate%20--%3E%20%7CSuccess%7C%20EnsureCfgDir%5B%22Ensure%20Configs%20directory%20exists%22%5D%0AEnsureCfgDir%20--%3E%20Copy%5B%22WithWriteAccess(overwrite%20Settings.json)%22%5D%0ACopy%20--%3E%20ApplyDone(%5B%22Finished%22%5D)%0A"})]),fallback:i(()=>e[2]||(e[2]=[t(" Loading... ")])),_:1})),e[8]||(e[8]=o('<h2 id="dependency-analysis" tabindex="-1">Dependency Analysis <a class="header-anchor" href="#dependency-analysis" aria-label="Permalink to &quot;Dependency Analysis&quot;">​</a></h2><ul><li>Profile Scheme Manager Dependencies: <ul><li>Application Root Path (used to concatenate Configs/Profiles and Settings.json)</li><li>Process Protection Manager (safe writing)</li><li>Logging (exceptions and warnings)</li></ul></li><li>Automatic Backup Manager Dependencies: <ul><li>Settings model (used for backup file validation)</li><li>Process Protection Manager (safe writing)</li><li>Application Root Path (Backups directory)</li></ul></li><li>Application Entry Point Dependencies: <ul><li>Main configuration file (Settings.json) existence and content parsing</li></ul></li></ul>',2)),(a(),s(l,null,{default:i(()=>[n(r,{id:"mermaid-252",class:"mermaid",graph:"graph%20LR%0AApp%5B%22App.xaml.cs%22%5D%20--%3E%20ST%5B%22Configs%2FSettings.json%22%5D%0ACfg%5B%22ConfigProfileManager%22%5D%20--%3E%20ST%0ACfg%20--%3E%20PR%5B%22Configs%2FProfiles%2F*%22%5D%0ACfg%20--%3E%20Proc%5B%22ProcessProtectionManager%22%5D%0ABk%5B%22AutoBackupManager%22%5D%20--%3E%20ST%0ABk%20--%3E%20BK%5B%22Backups%2F*%22%5D%0ABk%20--%3E%20Proc%0AST%20--%3E%20Model%5B%22Settings%20Model%22%5D%0A"})]),fallback:i(()=>e[3]||(e[3]=[t(" Loading... ")])),_:1})),e[9]||(e[9]=o('<h2 id="performance-considerations" tabindex="-1">Performance Considerations <a class="header-anchor" href="#performance-considerations" aria-label="Permalink to &quot;Performance Considerations&quot;">​</a></h2><ul><li>Safe Writing: Uses the Process Protection Manager&#39;s &quot;write latch + degraded lock release&quot; mechanism to avoid long blocks and reduce concurrent writing risks.</li><li>Directory Scanning: Auto-backup cleanup scans only auto-backup files with the correct prefix, avoiding useless processing of other files.</li><li>Minimal Parsing: The application entry point&#39;s parsing of Settings.json is a lightweight read, extracting only necessary fields to minimize overhead.</li></ul><p>[This section contains general suggestions and does not list specific file sources]</p><h2 id="troubleshooting-guide" tabindex="-1">Troubleshooting Guide <a class="header-anchor" href="#troubleshooting-guide" aria-label="Permalink to &quot;Troubleshooting Guide&quot;">​</a></h2><p>Common issues and recommended handling:</p><ul><li>Configuration file cannot be saved/overwritten <ul><li>Check whether process protection is enabled, and confirm if the write latch has timed out.</li><li>Verify if the target path exists and has write permissions.</li></ul></li><li>Applying scheme fails <ul><li>Confirm the scheme file exists and is not empty.</li><li>Verify that the scheme file can be successfully deserialized into Settings.</li></ul></li><li>Automatic backup not executed <ul><li>Check settings: check if enabled, last backup time, and backup interval.</li><li>Confirm Settings.json exists.</li></ul></li><li>Restoring from backup fails <ul><li>Check if the backup directory exists and the number of backup files.</li><li>Verify that the backup file can be successfully deserialized into Settings.</li><li>If a current configuration exists, it will be saved separately as a &quot;damaged backup&quot;.</li></ul></li><li>Splash screen not showing as expected <ul><li>Check the appearance.enableSplashScreen field in Settings.json.</li></ul></li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>InkCanvasForClass&#39;s configuration file management centers on &quot;Main Configuration + Multiple Schemes + Automatic Backups&quot;, utilizing process protection mechanisms to safeguard writing safety and integrity. Through explicit storage locations, file formats, and naming conventions, as well as robust loading, backup, and restore workflows, the system achieves excellent maintainability and robustness. It is recommended to follow data type and structural constraints when manually editing configurations, and to perform regular backups to mitigate risks.</p><p>[This section is summary content and does not list specific file sources]</p><h2 id="appendix" tabindex="-1">Appendix <a class="header-anchor" href="#appendix" aria-label="Permalink to &quot;Appendix&quot;">​</a></h2><h3 id="configuration-file-structure-and-naming-conventions" tabindex="-1">Configuration File Structure and Naming Conventions <a class="header-anchor" href="#configuration-file-structure-and-naming-conventions" aria-label="Permalink to &quot;Configuration File Structure and Naming Conventions&quot;">​</a></h3><ul><li>Main Configuration File: Configs/Settings.json (JSON)</li><li>Profile Schemes: Configs/Profiles/*.json (JSON, filename converted to &quot;safe filename&quot;)</li><li>Automatic Backup: Backups/Settings_AutoBackup_YYYYMMDD_HHmmss.json (JSON)</li><li>Hotkey Configuration: Configs/HotkeyConfig.json (JSON)</li></ul>',12))])}const E=g(f,[["render",m]]);export{y as __pageData,E as default};
